window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/humanas_2025.js"]=[{"title":"Poluentes também se deslocam com o ar","steps":["A imagem mostra a dispersão de material associado a queimadas entre áreas continentais separadas pelo Atlântico.","Gases e partículas podem ser transportados pelos ventos e pela circulação atmosférica, ultrapassando a região em que foram emitidos.","O mecanismo espacial pedido é a circulação de massas de ar: D. Temperatura ou insolação, isoladamente, não descrevem esse transporte."],"alternatives":{"A":"Amplitude térmica descreve diferenças de temperatura; não identifica diretamente o transporte de poluentes entre continentes.","B":"A insolação não é homogênea durante o ano e essa suposta homogeneidade não explica a dispersão representada.","C":"Chuvas de relevo dependem da elevação do ar por barreiras topográficas, não do transporte transatlântico mostrado.","D":"O deslocamento atmosférico transporta os poluentes para além das áreas de queimada, explicando sua dispersão.","E":"A ausência de frentes frias não é condição necessária nem informação demonstrada pelo mapa."},"takeaway":"Problemas ambientais atravessam fronteiras políticas quando o meio físico transporta seus efeitos.","key":"humanas:H445","area":"humanas","year":2025,"number":47,"answer":"D","subject":"Geografia","topic":"Climatologia e biomas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Persuadir não é demonstrar racionalmente","steps":["Hume descreve uma eloquência que domina imaginação e afetos, deixando pouco espaço para reflexão e razão.","A crítica é ao convencimento que obtém adesão sem assegurar verdade ou demonstração.","Essa associação aproxima o argumento das críticas platônicas à persuasão sofística: E. Trata-se de analogia, não de afirmar identidade completa entre Hume e Platão."],"alternatives":{"A":"A passagem não formula a objetividade do conhecimento em termos kantianos; o tema é a captura afetiva dos ouvintes.","B":"O debate medieval dos universais trata do estatuto de conceitos gerais, não do efeito persuasivo da eloquência.","C":"O trecho contrapõe a eloquência à reflexão, em vez de reduzi-la a demonstração lógica aristotélica.","D":"O método cartesiano busca critérios racionais; não corresponde ao domínio dos afetos descrito criticamente.","E":"A persuasão sem compromisso assegurado com a verdade é o ponto de aproximação com a crítica platônica aos sofistas."},"takeaway":"Compare a operação descrita no excerto com cada conceito, sem decidir apenas pelo nome conhecido do filósofo.","key":"humanas:H639","area":"humanas","year":2025,"number":48,"answer":"E","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Veneza e a rede mediterrânea","steps":["A pintura mostra pessoas com diferentes referências culturais convivendo no espaço urbano; o texto destaca a presença de orientais.","Essa condição cosmopolita relaciona-se ao papel de Veneza como entreposto entre circuitos do Mediterrâneo e do Oriente.","A integração comercial mediterrânea favorecia a circulação de mercadores, bens e costumes: C. O centro do argumento não é a conquista americana."],"alternatives":{"A":"O ensino laico não é indicado pela pintura ou pelo texto como explicação da presença de orientais.","B":"A expansão atlântica para a América não é o circuito histórico principal que explica o cosmopolitismo veneziano apresentado.","C":"As conexões comerciais do Mediterrâneo aproximavam grupos de procedências distintas, compondo o ambiente cosmopolita.","D":"O humanismo integra a história moderna, mas não é a conexão explicitada pelos exemplos de diversidade na cidade.","E":"Corporações de ofício organizavam atividades produtivas; sua existência não explica por si a integração entre regiões mostrada."},"takeaway":"Cosmopolitismo urbano pode revelar redes de circulação; relacione a cidade à posição ocupada nos fluxos históricos.","key":"humanas:H189","area":"humanas","year":2025,"number":49,"answer":"C","subject":"História Geral","topic":"Idade Moderna: Renascimento, Reforma e absolutismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Justiça e legalidade não são idênticas","steps":["Derrida distingue o direito, organizado por regras calculáveis, de uma justiça que não é automaticamente garantida pela regra.","O comando pede uma ação que possa ser justa mesmo contrariando o ordenamento jurídico.","A desobediência civil caracteriza precisamente a contestação consciente de uma norma em nome de uma exigência de justiça: A. Isso não torna qualquer infração justa."],"alternatives":{"A":"A desobediência civil pode violar uma norma para denunciar uma injustiça, ilustrando a tensão entre legalidade e justiça.","B":"A repressão estatal não é, por sua natureza, um exemplo de justiça que transcende a lei; pode inclusive perpetuar injustiças.","C":"Conflitos entre continentes não implicam motivação ética de contestar uma norma injusta.","D":"Manifestações sindicais podem ser legais ou não; a categoria não expressa necessariamente o contraste solicitado.","E":"Mobilizações estudantis também podem ocorrer dentro da lei; o exemplo específico de oposição jurídica é a desobediência civil."},"takeaway":"Distinguir justiça de legalidade não é legitimar qualquer ilegalidade: é examinar criticamente as próprias normas.","key":"humanas:H689","area":"humanas","year":2025,"number":50,"answer":"A","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pressa e fragilidade dos encontros","steps":["A conversa ocorre enquanto o sinal está fechado e é atravessada por pressa, promessas de telefonar e adiamento de um encontro.","Os interlocutores têm muito a dizer, mas o ritmo da vida urbana interrompe a convivência e dificulta aprofundar os vínculos.","A letra enfatiza a efemeridade das relações afetivas: D. O sinal de trânsito é cenário simbólico, não um estudo sobre a redução da mobilidade."],"alternatives":{"A":"“Pegar meu lugar no futuro” e a pressa não indicam redução da competição; a alternativa contraria o clima da letra.","B":"Há lembranças pessoais, mas não se discute a construção de uma memória coletiva como questão central.","C":"A canção representa circulação apressada e encontros interrompidos, não queda da mobilidade urbana.","D":"Promessas adiadas e despedida rápida mostram vínculos afetivos dificultados pela pressa cotidiana.","E":"O telefone é mencionado como possibilidade de contato; não se afirma que esteja obsoleto."},"takeaway":"Na fonte artística, ligue cenário e ritmo às relações sociais representadas; não trate todo objeto citado como tema central.","key":"humanas:H777","area":"humanas","year":2025,"number":51,"answer":"D","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Censura de guerra e nome da pandemia","steps":["O texto contrasta a Espanha neutra, com maior liberdade de imprensa, e os países envolvidos na Primeira Guerra.","O controle de notícias nos beligerantes limitava a divulgação de casos; a maior visibilidade espanhola favoreceu a associação indevida da doença ao país.","A denominação se relaciona ao controle dos relatos de guerra: C. O próprio trecho nega que o nome prove origem espanhola."],"alternatives":{"A":"O foco é a circulação de informações sob censura, não a qualidade dos conhecimentos da medicina militar.","B":"Não há relato de punição de desertores ou de retaliação que tenha dado nome à pandemia.","C":"O controle da informação nos países em guerra contrasta com a divulgação espanhola e ajuda a explicar a denominação.","D":"O texto não atribui a pandemia a armas biológicas; introduzir essa causa seria inventar informação.","E":"Refugiados e contaminação podem integrar histórias de epidemias, mas não explicam o nome segundo esse excerto."},"takeaway":"Nomes históricos podem refletir assimetrias de informação, não o lugar real de origem de um fenômeno.","key":"humanas:H242","area":"humanas","year":2025,"number":52,"answer":"C","subject":"História Geral","topic":"Guerras Mundiais e totalitarismos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Da condenação religiosa à adesão de fiéis","steps":["O texto I relata proibições, recusa de batismo e excomunhão associadas a teatro e dança.","O texto II descreve aceitação da dança litúrgica, divulgação, cursos e um mercado voltado a esse público religioso.","Os aspectos são, respectivamente, dogmatismo religioso e adesão de fiéis: E. A ordem dos textos é decisiva."],"alternatives":{"A":"O primeiro texto contém exclusão religiosa, mas o segundo enfatiza aceitação e expansão, não intolerância eclesiástica.","B":"Não se comparam dois sacramentos; o contraste está entre condenação da prática e sua incorporação posterior.","C":"Transe e progresso intelectual não são os mecanismos ou finalidades explicitados nas duas passagens.","D":"Não se descreve uma sequência de penitência individual e juramento coletivo como princípio da mudança.","E":"A condenação fundada em normas religiosas contrasta com a adesão e expansão da prática entre fiéis."},"takeaway":"Em comparações, respeite o “respectivamente” e caracterize cada texto antes de procurar o par de conceitos.","key":"humanas:H838","area":"humanas","year":2025,"number":53,"answer":"E","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Lugar: experiência e memória","steps":["O relato aproxima a Feira de São Cristóvão, a futura vida na Paraíba e a costura de Dona Didi às lembranças familiares.","Os espaços adquirem sentido por afetos, trajetórias e experiências, não apenas por localização ou atividade econômica.","São histórias conectadas e recordações do lugar: A. Na Geografia, lugar pode designar o espaço vivido e carregado de significados."],"alternatives":{"A":"As memórias articulam pessoas e espaços de convivência, compondo trajetórias afetivas e sentidos do lugar.","B":"O trabalho de costura aparece em casa; não se discutem direitos trabalhistas nem um sistema industrial.","C":"Não há exemplo de preconceito contra uma variedade de fala, embora existam deslocamentos entre regiões.","D":"O texto não narra lembranças de uma fábrica nem discriminação de operários, mas experiências familiares.","E":"Não se estabelece segregação regional como causa dos itinerários; a conexão central é afetiva e memorial."},"takeaway":"Lugar é espaço vivido: quando o texto aproxima geografia, memória e afeto, não o reduza a coordenadas.","key":"humanas:H553","area":"humanas","year":2025,"number":57,"answer":"A","subject":"Geografia","topic":"Cartografia, paisagem e tecnologias geográficas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reforma eleitoral e exclusão dos analfabetos","steps":["A Reforma de 1881, conhecida como Lei Saraiva, reorganizou eleições e introduziu exigência de alfabetização para votar.","Em uma sociedade com analfabetismo elevado, a regra excluiu grande parte da população antes participante, além das restrições já existentes.","A exigência de alfabetização explica a forte redução destacada: D. Mulheres já eram excluídas antes, logo isso não explica a mudança específica."],"alternatives":{"A":"A exclusão das mulheres já existia; não é a novidade da reforma que explica o corte do eleitorado apresentado.","B":"A restrição a imigrantes não é o fator central da redução vinculada à Reforma de 1881.","C":"Comprovação de domicílio não corresponde à principal barreira histórica destacada pelo problema.","D":"A alfabetização tornou-se requisito eleitoral e excluiu a grande população analfabeta, reduzindo a participação.","E":"A obrigatoriedade do sufrágio não explica uma queda tão grande: o problema é o acesso restrito ao direito de votar."},"takeaway":"Para explicar uma variação histórica, identifique o que mudou, não uma exclusão que já existia antes.","key":"humanas:H727","area":"humanas","year":2025,"number":58,"answer":"D","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Floresta, umidade e geração de energia","steps":["O texto vincula a redução da floresta à menor quantidade de água devolvida à atmosfera.","A evapotranspiração participa da circulação de umidade e das chuvas que abastecem bacias e reservatórios importantes para hidrelétricas.","A alteração da paisagem em locais estratégicos, como a Amazônia, prejudica essa dinâmica: B. O problema não é uma simples mudança de variável de pesquisa."],"alternatives":{"A":"O texto não atribui a crise a alterações metodológicas em pesquisas, mas a transformações reais da cobertura vegetal.","B":"Remover floresta em áreas importantes para a circulação de umidade interfere nas chuvas e na disponibilidade hídrica.","C":"A demanda industrial pode pressionar o sistema, mas não é a causa destacada pela explicação sobre floresta e chuva.","D":"Metas climáticas não modificam diretamente o ciclo da água como faz a transformação da paisagem descrita.","E":"Não se aponta mudança da geologia; a alteração focalizada é na vegetação e em seu papel hidrológico."},"takeaway":"Relacione floresta e energia pela cadeia evapotranspiração → chuvas → vazões e reservatórios.","key":"humanas:H575","area":"humanas","year":2025,"number":59,"answer":"B","subject":"Geografia","topic":"Recursos hídricos e energia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Lucro e responsabilidade ética","steps":["O excerto recusa reduzir açougueiro e padeiro a agentes movidos apenas por ganho financeiro.","Empatia e julgamento distinguem o que se deseja fazer daquilo que se considera devido em sociedade.","O lucro aparece associado à responsabilidade ética: D. Reconhecimento e satisfação podem existir, mas não são a base moral explicitada."],"alternatives":{"A":"Não se propõe concentrar poder político como motivação dos negócios; a discussão é sobre dever e empatia.","B":"A satisfação subjetiva não esgota o argumento, que distingue desejo pessoal e responsabilidade perante outros.","C":"Monopólio é uma estrutura de mercado; não é o fundamento ético apresentado para a ação econômica.","D":"O julgamento moral e a empatia limitam o interesse financeiro e expressam responsabilidade na vida social.","E":"O texto não reduz a moralidade à busca de aprovação pública; enfatiza o que se sente que se deve fazer."},"takeaway":"Não imponha ao autor um estereótipo: leia se o fragmento fala apenas de interesse ou também de obrigações morais.","key":"humanas:H615","area":"humanas","year":2025,"number":60,"answer":"D","subject":"Filosofia","topic":"Ética e filosofia política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Quem governa e em benefício de quem","steps":["Aristóteles usa dois critérios no fragmento: número de governantes e orientação ao bem comum ou ao interesse particular.","O comando pede a tríade clássica segundo um, poucos e muitos, apresentada na alternativa E como monarquia, aristocracia e democracia.","Atenção à nuance: na classificação aristotélica estrita, a forma reta dos muitos é politeia, e “democracia” pode nomear seu desvio. Aqui E é o gabarito oficial para a tríade numérica, não uma afirmação de que todos esses nomes sejam formas retas no autor."],"alternatives":{"A":"Tirania e oligarquia designam desvios no esquema aristotélico; o conjunto não corresponde à tríade numérica pedida.","B":"Burocracia, autarquia e império não formam a classificação clássica por um, poucos e muitos.","C":"Ditadura, autocracia e anarquia não representam os três termos da tríade solicitada.","D":"Plutocracia e tecnocracia classificam outros critérios de seleção do poder; não compõem o conjunto pedido.","E":"É a alternativa oficial que apresenta um, poucos e muitos. Não confunda esse uso geral de democracia com a terminologia estrita das formas retas e desviadas."},"takeaway":"Separe os eixos “quantos governam” e “para quem governam”; registre diferenças entre nomenclaturas antigas e atuais.","key":"humanas:H640","area":"humanas","year":2025,"number":61,"answer":"E","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Utopia como horizonte de transformação","steps":["Para Bauman, a utopia nasce de reconhecer problemas estruturais e confiar na capacidade humana de transformar o mundo.","Essa combinação permite imaginar formas diferentes de organização social e orientar a ação em direção a elas.","Sua função é apontar alternativas possíveis: B. O texto não promete uma solução final que elimine todos os problemas."],"alternatives":{"A":"Memórias afetivas não são as duas condições que o autor apresenta para a formação de uma utopia.","B":"A crítica do presente e a confiança na ação humana abrem possibilidades alternativas de organização social.","C":"A proposta é reformar fundamentos, não legitimar automaticamente experiências do passado.","D":"Perpetuar paradigmas fixos contraria o questionamento dos fundamentos que não funcionam adequadamente.","E":"O texto propõe um horizonte transformador, sem garantir respostas definitivas ou conclusivas para a história."},"takeaway":"Utopia pode orientar crítica e ação sem ser previsão garantida nem projeto acabado de sociedade.","key":"humanas:H839","area":"humanas","year":2025,"number":62,"answer":"B","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Capital agroindustrial e inserção mundial","steps":["O quadro mostra o destaque brasileiro na produção e exportação de diversos produtos agropecuários.","A expansão de capital agroindustrial integra insumos, mecanização, processamento, financiamento e logística, ampliando escala e conexão a mercados.","Essa modernização favorece o cenário mostrado: B. O quadro não demonstra que a liderança decorra de pequenas lavouras de subsistência."],"alternatives":{"A":"A redução do poder de compra interno não explica, sozinha, a capacidade produtiva e a inserção internacional em vários produtos.","B":"O investimento agroindustrial amplia escala, tecnologia e articulação das cadeias, favorecendo produção e exportações.","C":"A modernização demanda especialização em diversas etapas, não depende de uma diminuição geral desse tipo de trabalho.","D":"A valorização do real pode encarecer exportações em moeda estrangeira; não é a explicação proposta para o destaque produtivo.","E":"Cultivos de subsistência visam o consumo das famílias e não são o mecanismo principal de expansão das cadeias exportadoras mostradas."},"takeaway":"Agronegócio envolve cadeias e capital além da fazenda; não confunda liderança exportadora com agricultura de subsistência.","key":"humanas:H299","area":"humanas","year":2025,"number":63,"answer":"B","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Rua Tonelero e crise de 1954","steps":["O atentado contra Carlos Lacerda, crítico de Vargas e ligado à UDN, atingiu o jornalista e resultou na morte do major Rubens Vaz.","A ligação do crime a integrantes da guarda pessoal presidencial agravou a crise e fortaleceu a pressão oposicionista.","A consequência imediata foi a intensificação dos ataques udenistas: A. A mobilização popular favorável após o suicídio é outro momento da sequência."],"alternatives":{"A":"A UDN utilizou o atentado para ampliar a ofensiva política contra Vargas, agravando a crise de agosto de 1954.","B":"A intervenção sindical não é a consequência imediata central do atentado apresentada pelo contexto.","C":"A defesa popular do governo não corresponde ao efeito imediato solicitado; o episódio fortaleceu a oposição.","D":"O segundo governo Vargas não era o Estado Novo; não se deve transportar automaticamente a censura ditatorial para 1954.","E":"O problema não descreve uma simples transferência de apoio eleitoral a candidatos, mas a escalada da crise contra o presidente."},"takeaway":"Distinga segundo governo Vargas e Estado Novo e respeite a ordem: atentado, pressão oposicionista, desfecho da crise.","key":"humanas:H101","area":"humanas","year":2025,"number":64,"answer":"A","subject":"História do Brasil","topic":"Era Vargas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Altruísmo: agir pelo bem dos outros","steps":["A narradora define a pessoa que gostaria de ser como alguém que luta pelo bem dos outros.","A defesa de acusados e o sofrimento diante de injustiças sociais indicam atenção às necessidades e ao sofrimento alheios.","Esse princípio corresponde ao altruísmo: C. A menção a animais é um exemplo, mas não limita a preocupação a uma doutrina sobre espécies."],"alternatives":{"A":"Eudaimonia se refere ao florescimento ou vida boa; não nomeia tão especificamente a orientação ao benefício de outros destacada.","B":"Hedonismo toma prazer como referência; a passagem enfatiza defesa dos vulneráveis, não busca pessoal de prazer.","C":"A preocupação em agir pelo bem alheio, inclusive diante das injustiças, caracteriza o pensamento altruísta.","D":"A proteção dos animais aparece, mas o texto se amplia para pessoas e classes sociais; não formula especificamente o antiespecismo.","E":"Pragmatismo não é sinônimo de solidariedade: a preocupação central aqui é ética e voltada ao outro."},"takeaway":"Use a frase que define o princípio da ação, evitando reduzir o texto a um exemplo lateral.","key":"humanas:H616","area":"humanas","year":2025,"number":65,"answer":"C","subject":"Filosofia","topic":"Ética e filosofia política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Marcuse e a sociedade unidimensional","steps":["O trecho afirma que a satisfação de necessidades pode enfraquecer o inconformismo e fazer a oposição parecer inútil.","A integração ao sistema reduz a capacidade de imaginar alternativas e esvazia a função crítica da autonomia.","Essa absorção da crítica caracteriza a realidade unidimensional em Marcuse: D. O avanço técnico é contexto, não a definição do mecanismo."],"alternatives":{"A":"Gestão integrada é uma expressão administrativa genérica e não identifica a neutralização da crítica examinada.","B":"Relativismo moral discute a validade de valores; o trecho trata da incorporação e do enfraquecimento da oposição.","C":"A desobediência civil seria uma forma de contestação, enquanto o texto denuncia justamente a dificuldade crescente de contestar.","D":"A redução do espaço para pensar e agir além do sistema corresponde à crítica marcuseana da unidimensionalidade.","E":"Desenvolvimento tecnológico pode integrar essa sociedade, mas não basta para explicar a perda da função crítica."},"takeaway":"Uma sociedade pode permitir escolhas de consumo e ainda estreitar a capacidade de pensar alternativas ao próprio sistema.","key":"humanas:H691","area":"humanas","year":2025,"number":66,"answer":"D","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Função social da terra e desigualdade","steps":["A desapropriação está vinculada a trabalho degradante e infrações ambientais, violações da função social da propriedade.","O direito de propriedade não aparece como absoluto: deve atender a requisitos sociais, trabalhistas e ambientais.","A intervenção de justiça pode revisar relações desiguais de poder e riqueza: D. O caso não significa distribuir toda a terra de modo homogêneo."],"alternatives":{"A":"Aplicar a função social pode alterar a ordem agrária excludente, e não simplesmente manter suas relações existentes.","B":"O texto limita a propriedade que viola exigências sociais; não se reduz a legitimá-la incondicionalmente.","C":"A medida confronta interesses de proprietários infratores, não é apresentada como mecanismo de hegemonia das classes dominantes.","D":"Combater trabalho degradante e rever a destinação de uma propriedade infratora pode enfrentar desigualdades econômicas.","E":"Uma desapropriação específica não implica uniformização geral do tamanho ou da distribuição de todas as propriedades."},"takeaway":"Função social conecta uso da terra, trabalho e ambiente; não confunda intervenção corretiva com distribuição perfeitamente igual.","key":"humanas:H300","area":"humanas","year":2025,"number":67,"answer":"D","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Verticalização no espaço urbano","steps":["Na fotografia de Salvador, vários edifícios de muitos pavimentos se concentram na faixa urbanizada.","A expansão da ocupação em altura é chamada verticalização, processo associado ao uso intensivo do solo urbano.","O elemento diretamente visível corresponde a E. A imagem isolada não permite concluir que o mercado imobiliário esteja estagnado ou que os edifícios sejam moradias populares."],"alternatives":{"A":"Uma fotografia de edifícios não demonstra estagnação de preços, investimentos ou especulação imobiliária.","B":"Pode haver patrimônio histórico na paisagem, mas o traço dominante apontado pela concentração de prédios é a verticalização.","C":"Não se pode identificar a categoria de política habitacional apenas pela aparência geral das construções.","D":"Não há dados sobre a predominância de usos comerciais; edifícios altos também podem ter uso residencial.","E":"A concentração de construções de muitos andares evidencia ocupação vertical do espaço urbano."},"takeaway":"Em análise de imagem, priorize características observáveis e evite deduzir renda ou função sem dados.","key":"humanas:H392","area":"humanas","year":2025,"number":68,"answer":"E","subject":"Geografia","topic":"Urbanização e espaço urbano","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ação cruzadista e expectativa de salvação","steps":["O texto apresenta a possibilidade de leigos alcançarem graça sem abandonar seu estado social para ingressar no clero.","A condição descrita é partir ao Oriente para combater os considerados inimigos de Cristo, no contexto das Cruzadas.","Para esse imaginário, uma iniciativa de participação na ação religiosa oferecia caminho de salvação: C, ações voluntárias. A passagem não trata apenas de ritual litúrgico."],"alternatives":{"A":"O acesso à graça não é condicionado à escrita ou leitura de textos, e sim à participação na expedição.","B":"O excerto não centra a salvação em ritos da liturgia, mas na ação de partir e combater.","C":"A adesão à partida para o Oriente é a ação que, segundo o imaginário descrito, permitiria obter a graça.","D":"Não se apresenta a expectativa de chegada de um messias como condição para a salvação.","E":"As celebrações não são a condição destacada; o texto descreve uma mobilização prática de fiéis."},"takeaway":"Não generalize uma crença para toda a Idade Média: responda pelo caminho de salvação descrito nessa fonte.","key":"humanas:H169","area":"humanas","year":2025,"number":69,"answer":"C","subject":"História Geral","topic":"Idade Média","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dissolução do calcário e colapso","steps":["O subsolo contém calcário, rocha suscetível à dissolução por água levemente ácida.","A dissolução pode criar cavidades subterrâneas; quando o teto perde sustentação, o terreno superior sofre subsidência ou colapso.","Esse processo de alteração química da rocha é intemperismo químico: B. Chuva e mudanças na drenagem podem favorecer a instabilidade."],"alternatives":{"A":"Cristalização forma minerais ou estruturas; não explica a dissolução e abertura de cavidades no calcário.","B":"A ação química da água sobre a rocha pode gerar vazios que culminam no abatimento do terreno.","C":"Recompor vegetação ciliar não é o processo geológico que dissolve o substrato e produz a cratera.","D":"Não se descreve acúmulo de matéria orgânica como causa da falta de suporte do subsolo.","E":"Impermeabilizar pode afetar escoamento, mas o mecanismo principal indicado pelo calcário é sua dissolução química."},"takeaway":"Em relevo cárstico, ligue calcário, dissolução, cavidades e subsidência; não atribua todo desabamento à erosão superficial.","key":"humanas:H521","area":"humanas","year":2025,"number":70,"answer":"B","subject":"Geografia","topic":"Geologia, relevo e solos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Patrimônio como suporte de memória","steps":["O trecho do Muro de Berlim é apresentado como patrimônio histórico e cultural, inclusive pelos grafites que recebeu.","Sua preservação mantém uma referência material a experiências históricas compartilhadas, além de diferentes interpretações públicas do passado.","Demoli-lo para uma obra privada ameaça essa memória coletiva: A. O muro remanescente não funciona mais como fronteira política da cidade."],"alternatives":{"A":"A destruição do suporte material de uma experiência histórica pode violar a preservação da memória coletiva.","B":"O trecho preservado já é patrimônio, não a fronteira política operante que a demolição passaria a alterar.","C":"O texto não identifica o projeto imobiliário como arquitetura neoclássica; a classificação é inventada.","D":"Não se descreve rejeição de influências culturais orientais, mas disputa entre preservação e empreendimento imobiliário.","E":"O objetivo da obra é um condomínio de luxo; reorganizar transportes não é a finalidade apresentada."},"takeaway":"Patrimônio não é apenas algo antigo: é um bem ao qual grupos atribuem valor de memória e identidade.","key":"humanas:H260","area":"humanas","year":2025,"number":71,"answer":"A","subject":"História Geral","topic":"Cultura, memória e conhecimento histórico","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Heráclito: unidade na tensão dos opostos","steps":["Os fragmentos organizam pares: unido/separado, consonância/dissonância, dia/noite e guerra/paz.","Esses contrários não descrevem um universo imóvel ou puro caos: sua tensão participa da unidade e do movimento do cosmos.","A expressão da alternativa D, “distribuição dicotômica”, corresponde à ênfase nesses pares opostos. Não a leia como separação absoluta entre dois mundos sem relação."],"alternatives":{"A":"O trecho não enfatiza permanência sem transformação; sua organização destaca oposições e tensões.","B":"Não se afirma degradação progressiva da matéria ou decadência da natureza como princípio explicativo.","C":"A imobilidade contraria a associação de Heráclito ao devir e à articulação dinâmica de contrários.","D":"Os pares contrapostos explicitam a organização por oposições, articuladas em unidade, como indicado nos dois fragmentos.","E":"Tensão e oposição não equivalem a desordem sem princípio; o pensamento heraclitiano admite uma ordem do devir."},"takeaway":"Heráclito combina mudança e unidade dos contrários; oposição não implica caos nem separação absoluta.","key":"humanas:H641","area":"humanas","year":2025,"number":72,"answer":"D","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma prática, interpretações culturais diferentes","steps":["O texto afirma que europeus classificavam o canibalismo como barbárie e incapacidade de autogoverno.","Já entre os tupis descritos, o ritual era regrado e morrer nele podia conferir honra ao guerreiro.","O par correspondente, na ordem pedida, é selvageria para europeus e empoderamento para ameríndios: A. A leitura deve reconhecer a perspectiva de cada grupo, sem universalizar práticas de todos os povos indígenas."],"alternatives":{"A":"Selvageria corresponde ao juízo europeu; empoderamento traduz, no item, a honra e valorização ritual do guerreiro.","B":"Impetuosidade não expressa o julgamento de barbárie, e resistência não é a função ritual enfatizada.","C":"O texto atribui honra, não humilhação, à morte ritual do guerreiro no grupo mencionado.","D":"Não se contrapõe intolerância europeia a violência indígena nesses termos; o comando exige os significados atribuídos à prática.","E":"Repressão e justiça não são os sentidos apresentados nas duas perspectivas comparadas."},"takeaway":"Em contatos culturais, separe o significado interno de uma prática do julgamento etnocêntrico feito pelo observador.","key":"humanas:H001","area":"humanas","year":2025,"number":73,"answer":"A","subject":"História do Brasil","topic":"Brasil Colônia e povos indígenas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Direitos como construção histórica coletiva","steps":["Bobbio mostra que novos direitos surgem e antigos se transformam conforme necessidades, interesses, técnicas e conflitos sociais.","Isso contrasta com a ideia de um elenco de direitos pronto e idêntico em qualquer momento histórico.","Considerá-los convenções coletivas, C, expressa seu reconhecimento social e histórico. Não significa dizer que sua proteção seja dispensável ou meramente arbitrária."],"alternatives":{"A":"O texto relaciona direitos a condições e disputas históricas; não os apresenta como fenômenos que surgem sem processos sociais.","B":"Atemporalidade contraria a tese central de que os direitos se modificam conforme as condições históricas.","C":"O reconhecimento e a formulação de direitos resultam de processos coletivos situados historicamente.","D":"A explicação não reduz direitos a sobrevivências de crenças religiosas; destaca mudanças sociais e técnicas.","E":"Relações de poder importam, mas reduzir todo direito a imposição apaga necessidades, interesses e construção coletiva enfatizados."},"takeaway":"Historicidade dos direitos explica suas transformações; não é argumento para negar sua importância normativa.","key":"humanas:H728","area":"humanas","year":2025,"number":76,"answer":"C","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Tecnologia limpa não elimina mineração","steps":["O carro elétrico aparece como alternativa ao petróleo, mas o texto aponta dependência de metais de baixa concentração nas jazidas.","Extrair e processar esses minerais também consome recursos e pode gerar impactos. Minerais são recursos não renováveis em escala humana.","A contradição ambiental é a continuidade da necessidade de fontes não renováveis: A. A avaliação deve considerar a cadeia produtiva, não apenas a emissão no escapamento."],"alternatives":{"A":"Mesmo ao reduzir a dependência de petróleo, a tecnologia demanda minerais não renováveis e sua extração.","B":"O texto não apresenta padronização de modelos de produção como contradição ambiental central.","C":"A qualificação do trabalho não explica o limite ecológico mencionado sobre a disponibilidade de metais.","D":"Não se oferece análise de uma lei industrial insuficiente; a limitação é material e ligada aos recursos.","E":"Materiais recicláveis podem reduzir impactos; sua utilização não é a contradição destacada pela dependência mineral."},"takeaway":"Avalie tecnologias pelo ciclo de vida: fonte energética, materiais, produção, uso e descarte.","key":"humanas:H576","area":"humanas","year":2025,"number":77,"answer":"A","subject":"Geografia","topic":"Recursos hídricos e energia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Utilitarismo: punição como meio","steps":["Bentham define felicidade por prazer e ausência de dor e atribui ao governo promovê-la socialmente.","A punição é examinada por sua capacidade de impedir ações prejudiciais a essa finalidade, não como um fim valioso por si.","A justiça assume perspectiva consequencialista de aplicar meios para atingir um fim: A. O raciocínio não é o dever independente dos resultados."],"alternatives":{"A":"A punição é um instrumento avaliado pela finalidade de proteger e ampliar a felicidade social.","B":"Uma obrigação fundada apenas no dever aproxima-se de outra perspectiva ética, não do critério de consequências usado.","C":"O trecho não começa por princípios absolutos de direitos; fundamenta a avaliação na felicidade e no dano.","D":"Reconhecer uma prescrição não identifica o critério utilitarista de avaliar ações por suas consequências.","E":"O costume social não é a razão suficiente para punir; a avaliação depende do efeito sobre prazer e sofrimento."},"takeaway":"Na ética utilitarista, pergunte pelas consequências e pela finalidade; não confunda com agir por dever incondicional.","key":"humanas:H617","area":"humanas","year":2025,"number":79,"answer":"A","subject":"Filosofia","topic":"Ética e filosofia política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Sustentabilidade e cursos de água","steps":["O modelo proposto articula prudência ecológica, eficiência energética e equidade socioespacial.","O comando pede a medida que contradiz esse modelo. A canalização convencional reduz a complexidade dos rios e pode acelerar o escoamento, transferindo problemas para jusante.","Entre as opções, C é a intervenção incompatível com a integração ecológica defendida. Não significa negar qualquer obra hidráulica, mas avaliar a medida genérica no contexto do item."],"alternatives":{"A":"A coleta seletiva pode favorecer reciclagem e gestão de resíduos, coerentes com prudência ecológica.","B":"Reutilizar chuva pode reduzir demanda por água tratada e melhorar a gestão hídrica.","C":"A canalização convencional trata o curso como conduto e altera funções ecológicas e hidrológicas, contrariando o modelo apresentado.","D":"Arborização pode melhorar conforto térmico e qualidade ambiental, sendo compatível com o modelo.","E":"A educação ambiental pode fortalecer a consciência e participação comunitária exigidas pela cidade sustentável."},"takeaway":"Em comandos negativos, marque a exceção. Compare os efeitos ambientais da intervenção, não apenas seu aspecto de obra pública.","key":"humanas:H577","area":"humanas","year":2025,"number":80,"answer":"C","subject":"Geografia","topic":"Recursos hídricos e energia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Platão: governar orientado ao bem comum","steps":["A cidade justa é dirigida por filósofos e suas classes cumprem funções orientadas ao bem da pólis.","A cidade injusta, em contraste, submete o governo aos interesses econômicos particulares dos proprietários.","O poder político deve ser inseparável de uma orientação ética ao bem comum: E. A referência aos filósofos não legitima mera habilidade de convencer."],"alternatives":{"A":"O conhecimento importa ao governo filosófico, mas “relação intersubjetiva” não exprime a oposição central entre justiça e interesse privado.","B":"O texto descreve uma organização política racional, sem desenvolver mitos de origem do cosmos.","C":"A primazia da retórica não é o fundamento da cidade justa; convencer não equivale a conhecer o bem.","D":"Virtudes participam da filosofia platônica, mas a relação pedida aqui liga diretamente justiça e governo.","E":"A condução da cidade deve servir ao bem comum, articulando ética e exercício do poder político."},"takeaway":"Na cidade ideal platônica, a pergunta “quem governa?” depende de outra: “com que orientação para o bem comum?”.","key":"humanas:H642","area":"humanas","year":2025,"number":82,"answer":"E","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Imprensa e integração do império","steps":["A instalação da corte no Rio em 1808 exigiu organizar e legitimar um centro de poder na América portuguesa.","A impressão de informações, conhecimentos e documentos favorecia a circulação de referências comuns e a conexão das regiões com a autoridade central.","A função política mais abrangente era integrar o território ao poder central: D. Propagar diretrizes administrativas é um instrumento possível, mas não esgota esse projeto de legitimação."],"alternatives":{"A":"O excerto não reduz a tipografia a estabelecer normas ideológicas para outros periódicos; enfatiza a sustentação de um projeto imperial.","B":"Divulgar atos pode contribuir, mas a alternativa restringe o papel à administração das capitanias e não abrange a integração política destacada.","C":"A comunicação com metrópoles europeias não é a finalidade central da nova sede americana apresentada.","D":"A circulação impressa ajuda a articular regiões e legitimar o centro imperial sediado no Rio de Janeiro.","E":"O projeto não se limita a difundir publicações a elites em Portugal; envolve construir o novo centro de poder na América."},"takeaway":"Distinga um meio administrativo do objetivo político mais amplo que organiza a interpretação da fonte.","key":"humanas:H060","area":"humanas","year":2025,"number":83,"answer":"D","subject":"História do Brasil","topic":"Império e independência","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Pesquisa aplicada à prevenção de incêndios","steps":["O texto apresenta cooperação entre UFMG e Inpe, reunindo dados de satélite e modelagem computacional.","A combinação de focos de calor, relevo, vento, umidade e biomassa permite estimar risco, intensidade e direção do fogo.","O exemplo evidencia a importância da pesquisa acadêmica para a causa ambiental: D. As outras opções introduzem agentes ou práticas não demonstrados."],"alternatives":{"A":"Agricultura orgânica não é a tecnologia de monitoramento e previsão descrita no projeto.","B":"A infraestrutura viária pode importar em combate a incêndios, mas não é o objeto demonstrado pela modelagem.","C":"Cosmologias indígenas não são apresentadas como base do modelo citado; não se deve inserir essa fonte sem evidência.","D":"A universidade e o instituto de pesquisa produzem conhecimento aplicado à prevenção e ao combate ao fogo.","E":"O texto descreve instituições brasileiras e não apresenta interesses estrangeiros como explicação da ferramenta."},"takeaway":"Identifique as instituições e o que elas produzem: pesquisa científica também é instrumento concreto de política ambiental.","key":"humanas:H554","area":"humanas","year":2025,"number":84,"answer":"D","subject":"Geografia","topic":"Cartografia, paisagem e tecnologias geográficas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Duas avaliações do cinema","steps":["O texto I celebra o cinema como entretenimento e espaço de encontros e sociabilidade.","O texto II expressa preocupação com filmes inadequados e seus efeitos sobre crianças, criticando a seleção das sessões diurnas.","São argumentos contrários sobre o mesmo tipo de diversão: B. Cinema aparece em ambos, mas nenhum texto descreve uma mesma didática escolar."],"alternatives":{"A":"As conclusões diferem: um texto valoriza a experiência, enquanto o outro ressalta problemas para crianças.","B":"Os dois avaliam o cinema, com ênfases opostas de encanto e preocupação moral com a programação.","C":"A referência a colégios no texto II não transforma os dois textos em propostas sobre uma mesma didática escolar.","D":"Não se formulam regras teológicas ou uma doutrina religiosa de uso pedagógico do cinema.","E":"O assunto cultural é comum, mas as justificativas não são idênticas: apresentam avaliações contrastantes."},"takeaway":"Comparar fontes exige separar assunto comum e posição de cada autor; mesmo tema não significa mesma conclusão.","key":"humanas:H840","area":"humanas","year":2025,"number":85,"answer":"B","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Climatização e menor demanda hidrelétrica","steps":["A tecnologia transfere energia térmica entre edifício e subsolo, aproveitando a estabilidade térmica do solo.","Esse aproveitamento pode reduzir a necessidade de eletricidade para climatização convencional, sem significar ausência total de consumo elétrico.","Num sistema com participação relevante de hidrelétricas, a expansão dessa eficiência reduz a pressão sobre elas: C. Não substitui toda a matriz nem dispensa outras fontes renováveis."],"alternatives":{"A":"A tecnologia diversifica soluções e usos energéticos, em vez de homogeneizar toda a matriz produtiva.","B":"O efeito proposto é reduzir demanda convencional de climatização, não necessariamente aumentar o consumo residencial.","C":"A menor demanda elétrica para climatização pode aliviar o esforço de geração das hidrelétricas.","D":"Uma inovação em edifícios não implica estagnação do consumo em todas as unidades industriais.","E":"O aproveitamento térmico do solo não torna desnecessários recursos renováveis ou o restante do sistema energético."},"takeaway":"Eficiência e aproveitamento térmico podem reduzir demanda sem produzir diretamente toda a eletricidade consumida.","key":"humanas:H578","area":"humanas","year":2025,"number":86,"answer":"C","subject":"Geografia","topic":"Recursos hídricos e energia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A amplitude dos saberes tradicionais","steps":["A declaração inclui conhecimentos sobre sementes, medicamentos, recursos genéticos, fauna e flora, além de artes e tradições orais.","Essa variedade evidencia sistemas de conhecimento que articulam ciência, tecnologia, cultura e organização social.","O reconhecimento corresponde à complexidade dos saberes tradicionais: C. Não se restringe à subsistência nem significa aumentar influências externas."],"alternatives":{"A":"O repertório de direitos inclui línguas, mas não se reduz à classificação dos troncos linguísticos.","B":"O texto afirma controle e proteção do patrimônio pelos próprios povos, não a expansão de influências externas.","C":"A diversidade de conhecimentos e expressões reconhecidos mostra a complexidade e a amplitude desses saberes.","D":"Práticas de sobrevivência são apenas parte do conjunto; artes, literatura e recursos genéticos ampliam o alcance.","E":"O texto não apresenta diversificação econômica de subsistência como objetivo único ou central dos direitos."},"takeaway":"Saberes tradicionais não são apenas técnicas de sobrevivência: incluem conhecimento, linguagem, estética e direitos coletivos.","key":"humanas:H779","area":"humanas","year":2025,"number":88,"answer":"C","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Conhecimento e vida social em textos sagrados","steps":["O primeiro texto relaciona habilidade a desenhos, metais e artesanato; o segundo associa formação a palavras e obras.","O terceiro atribui ao conhecimento uma orientação para a conduta, afastando a ostentação. O conjunto conecta saber e práticas humanas.","A aproximação solicitada é o desenvolvimento social e as práticas laborais: E. Aqui “ciência” deve ser lida no contexto amplo de conhecimento, não como laboratório moderno."],"alternatives":{"A":"Os excertos não descrevem o surgimento histórico de universidades ou escolas confessionais.","B":"Não se apresentam crescimento de denominações ou disputas sectárias como efeito comum do conhecimento.","C":"O conteúdo não fundamenta intolerância e rivalidade entre nações; isso seria uma associação externa aos textos.","D":"Os trechos não se limitam à conservação de rituais místicos; destacam habilidades, obras e orientação da vida.","E":"Os saberes aparecem vinculados ao trabalho, às capacidades humanas e à organização da vida social."},"takeaway":"Evite anacronismo: uma fonte antiga pode falar em saber e habilidade sem formular o conceito moderno de ciência.","key":"humanas:H152","area":"humanas","year":2025,"number":89,"answer":"E","subject":"História Geral","topic":"Pré-História e Antiguidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Expedição científica e projeção imperial","steps":["A expedição recolhe materiais biológicos e etnográficos sul-americanos para instituições financiadoras sediadas no exterior.","No contexto de projeção nacional e imperial, classificar, coletar e centralizar saber sobre outros territórios também amplia prestígio e poder.","Além do valor científico, o projeto apresenta caráter imperialista e colonizador: A. Isso não autoriza inventar uma ocupação militar russa dos países visitados."],"alternatives":{"A":"A apropriação e centralização de coleções e conhecimentos relacionam a ciência à projeção de poder imperial sobre outros povos e territórios.","B":"O texto não descreve operação militar, treinamento de tropas ou disciplina imposta por uma força armada.","C":"A coleta para museus financiadores não é apresentada como diversão ou assistência filantrópica.","D":"Não há foco na venda comercial dos objetos como mercadorias; a projeção científica e nacional oferece o contexto mais adequado.","E":"Não se menciona missão religiosa nem assistência humanitária como propósito do empreendimento."},"takeaway":"Ciência e museus também têm história política. Reconheça relações de poder sem acrescentar fatos militares não documentados.","key":"humanas:H232","area":"humanas","year":2025,"number":90,"answer":"A","subject":"História Geral","topic":"Imperialismo e colonialismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2025_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/humanas/gab_2025.pdf","sha256":"583ac1950cd1927c42c971c270f96c0e33816844084fd5866a13bf94d8e08a81","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2025.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
